  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_lang_menu_sub` (`language`,`menu_id`,`submenu_id`)
) ENGINE=InnoDB AUTO_INCREMENT=142 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `assignments`;
CREATE TABLE `assignments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category` varchar(50) NOT NULL DEFAULT 'mechanics',
  `title` varchar(255) NOT NULL,
  `subtitle` varchar(255) DEFAULT '',
  `description` text DEFAULT NULL,
  `theory_equations` text DEFAULT NULL,
  `parameters` text DEFAULT NULL,
  `starter_code` longtext DEFAULT NULL,
  `solution_code` longtext DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


